<?php
function nstPayrollWorkbook($data,$period,$warehouse,$search,$payments,$user) {
 $book=new \PhpOffice\PhpSpreadsheet\Spreadsheet();$sheet=$book->getActiveSheet();$sheet->setTitle('Planilla');
 $book->getDefaultStyle()->getFont()->setName('Calibri')->setSize(11)->getColor()->setRGB('173E52');
 $text=function($s,$cell,$value){$s->setCellValueExplicit($cell,(string)$value,\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_STRING);};
 $header=function($s,$title,$cols,$headers)use($text,$period,$user){$end=\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($cols);$s->mergeCells('A1:'.$end.'1');$text($s,'A1',$title.' · '.$period);$s->getRowDimension(1)->setRowHeight(34);$s->getStyle('A1')->getFont()->setBold(true)->setSize(20);$s->mergeCells('A2:'.$end.'2');$text($s,'A2','Generado por: '.$user.' · '.(new DateTime('now',new DateTimeZone('America/Lima')))->format('d/m/Y H:i').' · Moneda: soles (PEN)');$s->mergeCells('A3:'.$end.'3');$text($s,'A3','Importes confirmados del periodo. Los pendientes de revisión no se consideran deuda calculada.');foreach($headers as $i=>$h)$text($s,\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($i+1).'5',$h);$s->getStyle('A5:'.$end.'5')->getFill()->setFillType('solid')->getStartColor()->setRGB('123F53');$s->getStyle('A5:'.$end.'5')->getFont()->setBold(true)->getColor()->setRGB('FFFFFF');$s->getRowDimension(5)->setRowHeight(32);$s->freezePane('C6');$s->setShowGridlines(false);$s->getPageSetup()->setPaperSize(9)->setOrientation('landscape')->setFitToWidth(1)->setFitToHeight(0);$s->getPageSetup()->setRowsToRepeatAtTopByStartAndEnd(1,5);};
 $headers=['Personal','DNI / documento','Cargo','Tienda','Fecha de ingreso','Fecha de pago','Banco del personal','Cuenta del personal','CCI','Sueldo configurado','Ingresos confirmados','Descuentos','Neto confirmado','Pagado / adelantos','Falta pagar','Estado','Confirmado por'];$header($sheet,'PLANILLA Y PAGOS',17,$headers);
 $liqs=[];foreach($data['planilla'] as $p)$liqs[$p['IdEmpleado']]=$p;$stores=[];foreach($data['almacenes'] as $a)$stores[$a['IdAlmacen']]=$a['Almacen'];$selected=[];$row=6;
 foreach($data['personal'] as $person){if(!$person['Activo']||($warehouse&&(int)$person['IdAlmacen']!==$warehouse)||($search!==''&&mb_stripos($person['Empleado'].' '.$person['DniRuc'],$search)===false))continue;
  $selected[$person['IdEmpleado']]=true;$p=$liqs[$person['IdEmpleado']]??null;$values=[$person['Empleado'],$person['DniRuc'],$person['Cargo'],$stores[$person['IdAlmacen']]??'Sin tienda',$person['FechaIngreso'],$person['FechaPagoPeriodo'],$person['Banco'],$person['NumeroCuenta'],$person['CCI'],(float)$person['Sueldo'],$p?(float)($p['Detalle']['Ingresos']??$p['Ingresos']??0):null,$p?(float)($p['Detalle']['Descuentos']??$p['Descuentos']??0):null,$p?(float)$p['Neto']:null,$p?(float)$p['Pagado']:null,$p?max(0,(float)$p['Saldo']):null,$p?((float)$p['Saldo']>0?'PENDIENTE':'PAGADO / SIN SALDO'):'PENDIENTE DE REVISAR',$p['UsuarioReg']??''];
  foreach($values as $i=>$v){$cell=\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($i+1).$row;if($i>=9&&$i<=14){if($v!==null)$sheet->setCellValue($cell,$v);}else $text($sheet,$cell,$v??'');}$sheet->getRowDimension($row)->setRowHeight(36);$row++;
 }
 if($row>6){$text($sheet,'A'.$row,'TOTALES CONFIRMADOS');foreach(range('K','O') as $col){$sheet->setCellValue($col.$row,'=SUM('.$col.'6:'.$col.($row-1).')');$sheet->getCell($col.$row)->setFormulaAttributes(['t'=>'normal']);}$sheet->getStyle('A'.$row.':Q'.$row)->getFont()->setBold(true);}
 $sheet->getStyle('J6:O'.$row)->getNumberFormat()->setFormatCode('#,##0.00');$sheet->setAutoFilter('A5:Q'.max(5,$row-1));
 $history=$book->createSheet();$history->setTitle('Pagos registrados');$header($history,'HISTORIAL DE PAGOS',11,['Personal','Documento','Periodo','Fecha','Concepto','Importe','Cuenta de salida','Referencia','Usuario que pagó','Estado','ID de pago']);$r=6;
 foreach($payments as $pay){if(!isset($selected[$pay['IdEmpleado']]))continue;$v=[$pay['Empleado'],$pay['DniRuc'],$pay['Periodo'],$pay['Fecha'],$pay['Tipo'],(float)$pay['Importe'],$pay['Cuenta'],$pay['Referencia'],$pay['UsuarioReg'],($pay['Anulado']||$pay['CajaAnulado'])?'ANULADO':'VIGENTE',$pay['IdPago']];foreach($v as $i=>$value){$cell=\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($i+1).$r;if($i===5)$history->setCellValue($cell,$value);else $text($history,$cell,$value);}$history->getRowDimension($r)->setRowHeight(30);$r++;}
 $history->getStyle('F6:F'.max(6,$r))->getNumberFormat()->setFormatCode('#,##0.00');$history->setAutoFilter('A5:K'.max(5,$r-1));
 foreach([[$sheet,17,$row],[$history,11,$r]] as $part){list($s,$cols,$last)=$part;$end=\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($cols);for($i=1;$i<=$cols;$i++)$s->getColumnDimension(\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($i))->setWidth($i===1?42:($i===8?27:20));$s->getStyle('A1:'.$end.max(6,$last))->getAlignment()->setWrapText(true)->setVertical('center');for($i=6;$i<$last;$i++)if($i%2===0)$s->getStyle('A'.$i.':'.$end.$i)->getFill()->setFillType('solid')->getStartColor()->setRGB('EEF7F9');$s->getPageSetup()->setPrintArea('A1:'.$end.max(6,$last));}
 $book->setActiveSheetIndex(0);return $book;
}
return function($app){
 $app->get('/planilla/excel',function($q,$r)use($app){
  $params=$q->getQueryParams();$summary=$app->subRequest('GET','/planilla/resumen',http_build_query($params));if($summary->getStatusCode()!==200)return $summary;
  $data=json_decode((string)$summary->getBody(),true);$period=$q->getParam('periodo')?:date('Y-m');$warehouse=(int)$q->getParam('idAlmacen');$search=trim((string)$q->getParam('buscar'));
  $s=$this->db->prepare('SELECT pg.*,pp.IdEmpleado,pp.Periodo,e.Empleado,e.DniRuc,cu.Cuenta,cb.Anulado CajaAnulado FROM Rhu_PlanillaPago pg JOIN Rhu_PlanillaPeriodo pp ON pp.IdPlanilla=pg.IdPlanilla JOIN Rhu_Empleado e ON e.IdEmpleado=pp.IdEmpleado JOIN Cb_Cuenta cu ON cu.IdCuenta=pg.IdCuenta JOIN Cb_CajaBanco cb ON cb.IdCajaBanco=pg.IdCajaBanco WHERE pp.Periodo=? ORDER BY pg.Fecha,pg.IdPago');$s->execute([$period]);
  $book=nstPayrollWorkbook($data,$period,$warehouse,$search,$s->fetchAll(PDO::FETCH_ASSOC),$_SESSION['user']??'');$file=tempnam(sys_get_temp_dir(),'nst-payroll-');try{(new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($book))->save($file);$r->getBody()->write(file_get_contents($file));}finally{if(is_file($file))unlink($file);}
  return $r->withHeader('Content-Type','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')->withHeader('Content-Disposition','attachment; filename="Planilla_'.$period.'.xlsx"')->withHeader('Cache-Control','private, no-store');
 });
};
